const GOAL_TEMPLATES=[{id:"khatma",icon:"📖",title:"ختمة كاملة",target:30,unit:"جزء",metric:"mushaf"},{id:"fasting9",icon:"🌙",title:"صيام التسع",target:9,unit:"يوم",metric:"fasting"},{id:"qiyam",icon:"🌃",title:"قيام كل ليلة",target:10,unit:"ليلة",metric:"qiyam"},{id:"takbeer1000",icon:"📿",title:"1000 تكبيرة",target:1e3,unit:"تكبيرة",metric:"takbeer"},{id:"sadaqah",icon:"💝",title:"صدقة يومية",target:10,unit:"يوم",metric:"charity"},{id:"dhikr",icon:"🤲",title:"أذكار الصباح والمساء",target:10,unit:"يوم",metric:"adhkar"}];async function getUserGoals(){try{return await(window.ZadStore?.getState("userGoals",[]))||[]}catch{return[]}}async function addGoal(templateId){const tpl=GOAL_TEMPLATES.find(t=>t.id===templateId);if(!tpl)return;const goals=await getUserGoals();if(goals.find(g=>g.id===templateId)){if(typeof showToast==="function")showToast("هذا الهدف مُضاف بالفعل");return}goals.push({...tpl,addedAt:Date.now(),current:0});await(window.ZadStore?.setState("userGoals",goals));renderGoals();if(typeof showToast==="function")showToast(`🎯 أُضيف هدف: ${tpl.title}`)}window.addGoal=addGoal;async function removeGoal(id){let goals=await getUserGoals();goals=goals.filter(g=>g.id!==id);await(window.ZadStore?.setState("userGoals",goals));renderGoals()}window.removeGoal=removeGoal;function computeGoalProgress(goal){const S=window.STATE||{};switch(goal.metric){case"mushaf":return S.mushaf?.juz||0;case"fasting":return Object.values(S.fasting||{}).filter(Boolean).length;case"takbeer":return S.takbeer?.total||0;case"charity":return(S.charityDone||[]).length;case"qiyam":return S.streak||0;case"adhkar":return Object.keys(S.adhkar||{}).length;default:return goal.current||0}}async function renderGoals(){const container=document.getElementById("goals-container");if(!container)return;const goals=await getUserGoals();let html="";if(goals.length===0){html+=`<div class="goals-empty">لم تحدد أهدافاً بعد — اختر من القوالب أدناه 👇</div>`}else{html+=`<div class="goals-active">`;goals.forEach(goal=>{const current=computeGoalProgress(goal);const pct=Math.min(Math.round(current/goal.target*100),100);const done=current>=goal.target;html+=`\n        <div class="goal-card ${done?"goal-done":""}">\n          <div class="goal-icon">${goal.icon}</div>\n          <div class="goal-body">\n            <div class="goal-title">${goal.title} ${done?"✅":""}</div>\n            <div class="goal-progress-bar"><span style="width:${pct}%"></span></div>\n            <div class="goal-stats">${current} / ${goal.target} ${goal.unit} (${pct}%)</div>\n          </div>\n          <button class="goal-remove" onclick="removeGoal('${goal.id}')" aria-label="حذف">✕</button>\n        </div>`});html+=`</div>`}const activeIds=goals.map(g=>g.id);const available=GOAL_TEMPLATES.filter(t=>!activeIds.includes(t.id));if(available.length){html+=`<div class="goals-templates-title">أضف هدفاً</div>`;html+=`<div class="goals-templates">`;available.forEach(t=>{html+=`\n        <button class="goal-template" onclick="addGoal('${t.id}')">\n          <span class="gt-icon">${t.icon}</span>\n          <span class="gt-title">${t.title}</span>\n          <span class="gt-target">${t.target} ${t.unit}</span>\n        </button>`});html+=`</div>`}container.innerHTML=html}const GOALS_CSS=`\n.goals-empty { text-align: center; padding: 24px; color: var(--muted, #888); }\n.goal-card { display: flex; align-items: center; gap: 14px; padding: 16px; border-radius: 14px;\n  background: var(--sand, #faf9f6); border: 1.5px solid var(--border, #ddd); margin-bottom: 12px; }\n.goal-card.goal-done { background: rgba(14,59,46,.06); border-color: var(--zad-green-700, #1a5d47); }\n.goal-icon { font-size: 28px; }\n.goal-body { flex: 1; }\n.goal-title { font-weight: 800; font-size: 15px; margin-bottom: 6px; }\n.goal-progress-bar { height: 8px; background: var(--border, #e5e5e5); border-radius: 4px; overflow: hidden; margin-bottom: 4px; }\n.goal-progress-bar span { display: block; height: 100%; background: var(--zad-green-700, #1a5d47); border-radius: 4px; transition: width .4s; }\n.goal-stats { font-size: 12px; color: var(--muted, #888); }\n.goal-remove { background: none; border: none; color: var(--muted, #aaa); font-size: 16px; cursor: pointer; padding: 8px; }\n.goals-templates-title { font-size: 16px; font-weight: 800; margin: 24px 0 12px; }\n.goals-templates { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; }\n.goal-template { padding: 14px; border-radius: 12px; border: 1.5px solid var(--border, #ddd); background: var(--card, #fff);\n  cursor: pointer; text-align: center; font-family: inherit; transition: all .2s; }\n.goal-template:hover { border-color: var(--zad-green-700, #1a5d47); }\n.gt-icon { display: block; font-size: 24px; }\n.gt-title { display: block; font-weight: 700; font-size: 13px; margin: 4px 0 2px; }\n.gt-target { display: block; font-size: 11px; color: var(--muted, #888); }\n`;function injectGoalsCSS(){if(document.getElementById("goals-css"))return;const s=document.createElement("style");s.id="goals-css";s.textContent=GOALS_CSS;document.head.appendChild(s)}document.addEventListener("DOMContentLoaded",()=>{if(document.getElementById("goals-container")){injectGoalsCSS();renderGoals();console.log("[GoalsModule] ✅ موديول الأهداف الشخصية جاهز")}});window.GOAL_TEMPLATES=GOAL_TEMPLATES;window.renderGoals=renderGoals;